/**
 * PARADIS — Search Engine
 * Client-side full-text search over all course content using Fuse.js.
 * The search index is generated by mkdocs at build time and placed
 * at /search/search_index.json (served from the same origin).
 */
(function () {
    'use strict';

    let fuse = null;
    let indexBuilt = false;

    /**
     * Build the Fuse.js index from mkdocs search output.
     * Called on first search request.
     * @returns {Promise<Fuse|null>}
     */
    async function buildIndex() {
        if (indexBuilt && fuse) return fuse;
        try {
            // Dynamically import Fuse.js (CDN fallback for offline-first)
            const Fuse = await import('https://cdn.jsdelivr.net/npm/fuse.js@7/dist/fuse.esm.min.js');
            const response = await fetch('/search/search_index.json');
            if (!response.ok) throw new Error('Search index not found');
            const data = await response.json();
            fuse = new Fuse.default(data, {
                keys: [
                    { name: 'title', weight: 0.6 },
                    { name: 'tags', weight: 0.3 },
                    { name: 'summary', weight: 0.1 }
                ],
                threshold: 0.35,
                includeMatches: true,
                minMatchCharLength: 2,
                ignoreLocation: true,
                findAllMatches: false
            });
            indexBuilt = true;
            return fuse;
        } catch (err) {
            console.warn('Search index unavailable, using fallback:', err.message);
            fuse = null;
            return null;
        }
    }

    /**
     * Search across all lessons.
     * @param {string} query
     * @returns {Promise<Array>}
     */
    async function search(query) {
        const engine = await buildIndex();
        if (!engine || !query || query.trim().length < 2) return [];
        return engine.search(query.trim()).map(r => r.item);
    }

    /**
     * Reset the index (useful after content updates).
     */
    async function resetIndex() {
        fuse = null;
        indexBuilt = false;
    }

    window.ParadisSearch = { buildIndex, search, resetIndex };
})();
